testo:
{
 "genere": "prevedi",
 "titolo": "Ripasso: Prima persona e interazione",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted

func run():
	var ray := RayCast3D.new()
	ray.target_position = Vector3(0, 0, -5)
	return ray.target_position.z
",
   "domanda": "Quanto vale la coordinata z di `target_position`?",
   "spiegazione": "`target_position` viene impostato esplicitamente a `Vector3(0, 0, -5)`, quindi la coordinata z restituita è `-5`."
  },
  {
   "codice": "extends RefCounted

class DummyItem:
	func interact() -> void:
		pass

func run():
	var item = DummyItem.new()
	return item.has_method("interact")
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "La classe interna `DummyItem` possiede il metodo `interact()`. Il controllo con `has_method("interact")` restituisce quindi `true`, sfruttando il duck typing."
  },
  {
   "codice": "extends RefCounted

func run():
	var ray := RayCast3D.new()
	ray.target_position = Vector3(0, 0, -2.0)
	ray.target_position *= 3.0
	return ray.target_position.z
",
   "domanda": "Quanto vale la coordinata z di `target_position` alla fine?",
   "spiegazione": "`target_position` parte da `-2.0` sulla z. Moltiplicando il vettore per `3.0`, anche la z viene moltiplicata per 3, diventando `-6.0`."
  },
  {
   "codice": "extends RefCounted

class EmptyObject:
	pass

func run():
	var obj = EmptyObject.new()
	return obj.has_method("interact")
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "L'oggetto `EmptyObject` non ha alcun metodo `interact` definito al suo interno, quindi `has_method("interact")` restituisce `false`."
  },
  {
   "codice": "extends RefCounted

func run():
	var ray := RayCast3D.new()
	var collider = ray.get_collider()
	return collider == null
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "Un `RayCast3D` appena creato e non inserito in una scena attiva non rileva alcuna collisione, quindi `get_collider()` restituisce `null`. Il confronto `collider == null` risulta quindi `true`."
  }
 ]
